export interface CdpTargetApi {
  /** Activates (focuses) the target. */
  readonly activateTarget: (
    params: Protocol.Target.ActivateTargetRequest,
    sessionId?: string,
  ) => Effect.Effect<void, CdpProtocolError>;
  /** Attaches to the target with given id. */
  readonly attachToTarget: (
    params: Protocol.Target.AttachToTargetRequest,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.AttachToTargetResponse, CdpProtocolError>;
  /** Attaches to the browser target, only uses flat sessionId mode. */
  readonly attachToBrowserTarget: (
    params?: Record<string, never>,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.AttachToBrowserTargetResponse, CdpProtocolError>;
  /** Closes the target. If the target is a page that gets closed too. */
  readonly closeTarget: (
    params: Protocol.Target.CloseTargetRequest,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.CloseTargetResponse, CdpProtocolError>;
  /**
   * Inject object to the target's main frame that provides a communication
   * channel with browser target.
   * Injected object will be available as `window[bindingName]`.
   * The object has the following API:
   * - `binding.send(json)` - a method to send messages over the remote debugging protocol
   * - `binding.onmessage = json => handleMessage(json)` - a callback that will be called for the protocol notifications and command responses.
   */
  readonly exposeDevToolsProtocol: (
    params: Protocol.Target.ExposeDevToolsProtocolRequest,
    sessionId?: string,
  ) => Effect.Effect<void, CdpProtocolError>;
  /**
   * Creates a new empty BrowserContext. Similar to an incognito profile but you can have more than
   * one.
   */
  readonly createBrowserContext: (
    params: Protocol.Target.CreateBrowserContextRequest,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.CreateBrowserContextResponse, CdpProtocolError>;
  /** Returns all browser contexts created with `Target.createBrowserContext` method. */
  readonly getBrowserContexts: (
    params?: Record<string, never>,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.GetBrowserContextsResponse, CdpProtocolError>;
  /** Creates a new page. */
  readonly createTarget: (
    params: Protocol.Target.CreateTargetRequest,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.CreateTargetResponse, CdpProtocolError>;
  /** Detaches session with given id. */
  readonly detachFromTarget: (
    params: Protocol.Target.DetachFromTargetRequest,
    sessionId?: string,
  ) => Effect.Effect<void, CdpProtocolError>;
  /**
   * Deletes a BrowserContext. All the belonging pages will be closed without calling their
   * beforeunload hooks.
   */
  readonly disposeBrowserContext: (
    params: Protocol.Target.DisposeBrowserContextRequest,
    sessionId?: string,
  ) => Effect.Effect<void, CdpProtocolError>;
  /** Returns information about a target. */
  readonly getTargetInfo: (
    params: Protocol.Target.GetTargetInfoRequest,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.GetTargetInfoResponse, CdpProtocolError>;
  /** Retrieves a list of available targets. */
  readonly getTargets: (
    params: Protocol.Target.GetTargetsRequest,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.GetTargetsResponse, CdpProtocolError>;
  /**
   * Sends protocol message over session with given id.
   * Consider using flat mode instead; see commands attachToTarget, setAutoAttach,
   * and crbug.com/991325.
   */
  readonly sendMessageToTarget: (
    params: Protocol.Target.SendMessageToTargetRequest,
    sessionId?: string,
  ) => Effect.Effect<void, CdpProtocolError>;
  /**
   * Controls whether to automatically attach to new targets which are considered
   * to be directly related to this one (for example, iframes or workers).
   * When turned on, attaches to all existing related targets as well. When turned off,
   * automatically detaches from all currently attached targets.
   * This also clears all targets added by `autoAttachRelated` from the list of targets to watch
   * for creation of related targets.
   * You might want to call this recursively for auto-attached targets to attach
   * to all available targets.
   */
  readonly setAutoAttach: (
    params: Protocol.Target.SetAutoAttachRequest,
    sessionId?: string,
  ) => Effect.Effect<void, CdpProtocolError>;
  /**
   * Adds the specified target to the list of targets that will be monitored for any related target
   * creation (such as child frames, child workers and new versions of service worker) and reported
   * through `attachedToTarget`. The specified target is also auto-attached.
   * This cancels the effect of any previous `setAutoAttach` and is also cancelled by subsequent
   * `setAutoAttach`. Only available at the Browser target.
   */
  readonly autoAttachRelated: (
    params: Protocol.Target.AutoAttachRelatedRequest,
    sessionId?: string,
  ) => Effect.Effect<void, CdpProtocolError>;
  /**
   * Controls whether to discover available targets and notify via
   * `targetCreated/targetInfoChanged/targetDestroyed` events.
   */
  readonly setDiscoverTargets: (
    params: Protocol.Target.SetDiscoverTargetsRequest,
    sessionId?: string,
  ) => Effect.Effect<void, CdpProtocolError>;
  /**
   * Enables target discovery for the specified locations, when `setDiscoverTargets` was set to
   * `true`.
   */
  readonly setRemoteLocations: (
    params: Protocol.Target.SetRemoteLocationsRequest,
    sessionId?: string,
  ) => Effect.Effect<void, CdpProtocolError>;
  /**
   * Gets the targetId of the DevTools page target opened for the given target
   * (if any).
   */
  readonly getDevToolsTarget: (
    params: Protocol.Target.GetDevToolsTargetRequest,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.GetDevToolsTargetResponse, CdpProtocolError>;
  /** Opens a DevTools window for the target. */
  readonly openDevTools: (
    params: Protocol.Target.OpenDevToolsRequest,
    sessionId?: string,
  ) => Effect.Effect<Protocol.Target.OpenDevToolsResponse, CdpProtocolError>;
}

